// returns the zero value of its result in place of the field of its
// request over a fresh subject.
func mixedFillDropsTheField(h *MixedHandle) returnsonerror.Mixed {
	return &mixedFillDropsTheFieldDefect{mixedOverEmbedded: h.Fresh()}
}

